B.Mw=new A.dg(B.L,B.m,B.n,B.B,null,B.a0,null,0,B.Ti,null)
B.abV=new A.c1("La couleur de chaque barre indique o\xf9 vous en \xeates par rapport \xe0 votre plage cible.",!1,!1,null)
B.h5=new A.cq(null,16,null,null)
